#!/usr/bin/env python3
"""
patch-158-D — Multi-asset appointment show view (read-only).

Fourth patch in the multi-asset arc. Renders the appointment detail
page in the asset-grouped layout when:
  1) tenant has multi_asset_enabled = true, AND
  2) the appointment has at least one attached appointment_asset.

Otherwise the existing 2,579-line show.blade.php renders as-is.
No existing behavior changes for tenants without the flag.

Scope: READ-ONLY render. No mutations, no JS state, no controllers.
Patch E lands the interactive bits: attach asset modal, add service to
asset modal, totals recalc, status transitions, payment, charges.

What ships:
  - AppointmentController::show branches to show-multi-asset view
    when conditions met. Eager-loads appointmentAssets with their
    items.serviceItem + addons.addon + customerAsset.
  - show-multi-asset.blade.php (new): renders
    * Header with status pill + summary line
    * Customer card with View customer link
    * Asset cards in sort_order, each with:
      - Numbered head with name, identifier_snapshot, last-seen hint
      - "Existing" pill if asset came from customer's persistent list
      - Pinned services (tenant_appointment_items where appointment_asset_id matches)
      - Pinned add-ons
      - Per-asset subtotal
    * "Unassigned services" loose-items card if any items have NULL
      appointment_asset_id (back-compat for hybrid appointments)
    * Right rail: Totals (computed live from rollups), Schedule,
      Internal note, Payment status
    * "Coming in 158-E" disabled placeholders for the interactive bits

Existing single-asset appointments continue to use show.blade.php since
they have no rows in tenant_appointment_assets. To flip an existing
appointment into the multi-asset view, attach an asset to it (the
UI for that lands in 158-E; for now you can do it via tinker).

Manual test for 158-D:
  1. On a tenant with multi_asset_enabled = true (e.g. fitness):
  2. Find an appointment ID, then in tinker:
     >> $appt = App\Models\Tenant\TenantAppointment::find('...');
     >> $asset = App\Models\Tenant\TenantCustomerAsset::create([
          'tenant_id' => $appt->tenant_id,
          'customer_id' => $appt->customer_id,
          'name' => 'Test bike',
          'identifier' => 'TEST-001',
        ]);
     >> App\Models\Tenant\TenantAppointmentAsset::create([
          'tenant_id' => $appt->tenant_id,
          'appointment_id' => $appt->id,
          'customer_asset_id' => $asset->id,
          'asset_name_snapshot' => $asset->name,
          'identifier_snapshot' => $asset->identifier,
          'sort_order' => 0,
          'subtotal_cents' => 0,
        ]);
  3. Visit /admin/appointments/<id> — should render the new layout.
  4. Visit an appointment without attached assets — should render the
     legacy show.blade.php as before.

Standalone Python. Idempotent.
"""
import argparse, base64, pathlib, sys

